def _apply_cr_bp():
    import numpy as _np
    import sndlib as _sl
    tg_all = _sl.targets()
    for path, bp in CR_BP.items():
        d = tg_all.get(path)
        if d is None:
            continue
        if bp.get("ons"):
            d["onset_times_s"] = list(bp["ons"])
        env = bp["env"]
        d["bp_env"] = {"hop": bp["hop"], "v": list(env)}
        d["peak_time_s"] = float(int(_np.argmax(env))) * bp["hop"]
        # 11 tenth-of-file samples consistent with the contour (dB relative to an assumed -10 dB peak)
        nf = len(env)
        d["envelope_db_by_tenth"] = [float(env[min(nf - 1, int(round(k * (nf - 1) / 10.0)))]) - 10.0 for k in range(11)]


def _patch_tg():
    import numpy as _np
    import sndlib as _sl
    if getattr(_sl.Tg, "_cr_patched", False):
        return
    _orig = _sl.Tg.rel_env_pts

    def rel_env_pts(self):
        be = self.d.get("bp_env")
        if be:
            v = _np.maximum(_np.array(be["v"], float), -80.0)
            return _np.arange(len(v)) * be["hop"], v
        return _orig(self)

    _sl.Tg.rel_env_pts = rel_env_pts
    _sl.Tg._cr_patched = True


_patch_tg()
_apply_cr_bp()


def _patch_rel_env_at():
    import numpy as _np
    _orig = _so.rel_env_at

    def rel_env_at(tg, t):
        be = tg.d.get("bp_env")
        if be:
            v = _np.array(be["v"], float)
            return float(_np.interp(t, _np.arange(len(v)) * be["hop"], _np.maximum(v, -80.0)))
        return _orig(tg, t)

    _so.rel_env_at = rel_env_at


_patch_rel_env_at()


